export type SignalingRole = "host" | "guest";

/** Messages generated by the signaling room itself. Everything else is relayed verbatim from the peer. */
export type RoomMessage =
  /** `expiresInMs`: time left before the room closes (absent from older Workers). */
  | { type: "welcome"; role: SignalingRole; peerPresent: boolean; expiresInMs?: number }
  | { type: "peer-joined"; role: SignalingRole }
  | { type: "peer-left"; role: SignalingRole };

export type PeerMessage =
  | { type: "offer"; sdp: string }
  | { type: "answer"; sdp: string }
  | { type: "ice"; candidate: RTCIceCandidateInit | null };

export type SignalingMessage = RoomMessage | PeerMessage;

/**
 * Base URL of the signaling Worker. Set VITE_SIGNALING_URL at build time in
 * production (e.g. wss://photo-dojo-signaling.example.workers.dev). Otherwise
 * it's the page's own origin: the Vite dev server proxies /room to wrangler dev.
 */
export function signalingBaseUrl(
  env: { VITE_SIGNALING_URL?: string } = import.meta.env,
  loc: Pick<Location, "protocol" | "host"> = location,
): string {
  if (env.VITE_SIGNALING_URL) return env.VITE_SIGNALING_URL.replace(/\/+$/, "");
  return `${loc.protocol === "https:" ? "wss:" : "ws:"}//${loc.host}`;
}

export function signalingUrl(roomCode: string, role: SignalingRole, base = signalingBaseUrl()): string {
  return `${base}/room/${encodeURIComponent(roomCode)}?role=${role}`;
}

/** The HTTP(S) origin of the Worker, for non-WebSocket routes like TURN credentials. */
export function signalingHttpBase(base = signalingBaseUrl()): string {
  return base.replace(/^ws(s?):/, "http$1:");
}

type Handler = (message: SignalingMessage) => void;

/** WebSocket to the Worker's room; exchanges SDP/ICE as JSON. */
export class SignalingClient {
  private handlers = new Set<Handler>();
  private closeHandlers = new Set<(ev: CloseEvent) => void>();

  private constructor(private readonly socket: WebSocket, readonly role: SignalingRole, readonly roomCode: string) {
    socket.addEventListener("message", (ev) => {
      if (typeof ev.data !== "string") return;
      let msg: SignalingMessage;
      try {
        msg = JSON.parse(ev.data);
      } catch {
        return;
      }
      for (const h of this.handlers) h(msg);
    });
    socket.addEventListener("close", (ev) => { for (const h of this.closeHandlers) h(ev); });
  }

  /** Resolves once the socket is open and the room has welcomed us. */
  static connect(roomCode: string, role: SignalingRole, url = signalingUrl(roomCode, role)): Promise<{ client: SignalingClient; welcome: Extract<RoomMessage, { type: "welcome" }> }> {
    return new Promise((resolve, reject) => {
      const socket = new WebSocket(url);
      const client = new SignalingClient(socket, role, roomCode);
      const off = client.onMessage((msg) => {
        if (msg.type === "welcome") {
          off();
          resolve({ client, welcome: msg });
        }
      });
      socket.addEventListener("error", () => reject(new Error("Couldn't reach the signaling server")), { once: true });
      socket.addEventListener("close", (ev) => reject(new Error(ev.reason || `Signaling closed (${ev.code})`)), { once: true });
    });
  }

  get isOpen(): boolean {
    return this.socket.readyState === WebSocket.OPEN;
  }

  send(message: PeerMessage): void {
    if (this.isOpen) this.socket.send(JSON.stringify(message));
  }

  onMessage(handler: Handler): () => void {
    this.handlers.add(handler);
    return () => this.handlers.delete(handler);
  }

  onClose(handler: (ev: CloseEvent) => void): () => void {
    this.closeHandlers.add(handler);
    return () => this.closeHandlers.delete(handler);
  }

  close(): void {
    this.socket.close(1000, "done");
  }
}
